-- Nexmark q3 on flink, BLACKHOLE sink variant. Local item suggestion: auction
-- joined to person on seller, filtered to one category. Stream-stream equi-
-- join.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE auction (
  `id` BIGINT, `itemname` STRING, `initialbid` BIGINT, `reserve` BIGINT, `expires` BIGINT, `seller` BIGINT, `category` BIGINT, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-auction',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q3bh-auction',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE person (
  `id` BIGINT, `name` STRING, `emailaddress` STRING, `city` STRING, `state` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-person',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q3bh-person',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q3 (`name` STRING, `city` STRING, `state` STRING, `id` BIGINT) WITH ('connector' = 'blackhole');
INSERT INTO sink_q3
SELECT P.name, P.city, P.state, A.id FROM auction AS A JOIN person AS P ON A.seller = P.id WHERE A.category = 10;
